import base64, gzip, os, subprocess

XUI_DATA = ""
PROV_DATA = ""

app_dir = "/opt/vpn_store" if os.path.exists("/opt/vpn_store") else os.getcwd()

xui_path = os.path.join(app_dir, "app/services/xui_client.py")
prov_path = os.path.join(app_dir, "app/services/vpn_provisioner.py")

with open(xui_path, "wb") as f:
    f.write(gzip.decompress(base64.b64decode(XUI_DATA)))
print("✓ Updated:", xui_path)

with open(prov_path, "wb") as f:
    f.write(gzip.decompress(base64.b64decode(PROV_DATA)))
print("✓ Updated:", prov_path)

# Clear __pycache__
os.system("find " + app_dir + " -name '*.pyc' -delete 2>/dev/null")
os.system("find " + app_dir + " -type d -name '__pycache__' -exec rm -rf {} + 2>/dev/null")

# Restart services
os.system("pkill -9 -f uvicorn 2>/dev/null; pkill -9 -f 'app.bot.bot' 2>/dev/null")
os.system("systemctl daemon-reload && systemctl restart vpnstore-web vpnstore-bot")
print("✓ All services restarted cleanly with new code!")
